-- Forward-only row locks for the independently demonstrated concurrent grant-revocation race.
-- Original authenticated capture time and SQL storage time are distinct immutable observations.
-- The server verifies exact encrypted capture/review timestamps; retain both without rewriting history.
CREATE OR REPLACE FUNCTION public.communications_resolve_untracked_outbound(p_request uuid,p_binding uuid,p_event text) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,communications AS $$
DECLARE org text:=current_setting('app.acquire_org',true);actor text:=current_setting('app.acquire_user',true);b public.communication_bindings%ROWTYPE;a public.audit_events%ROWTYPE;r public.communication_event_receipts%ROWTYPE;l public.communication_reply_review_latches%ROWTYPE;p jsonb;e communications.events%ROWTYPE;w communications.webhook_inbox%ROWTYPE;sl communications.reply_review_latches%ROWTYPE;reference text:='human-unrelated:'||p_request::text;
BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'acquire_campaign_user' OR org IS NULL OR actor IS NULL OR NOT EXISTS(SELECT 1 FROM public.communication_send_gates WHERE organization_id=org AND writer_xid=txid_current()) OR NOT public.communications_lock_reply_member(org,actor) THEN RAISE EXCEPTION 'Untracked outbound review scope unavailable';END IF;
 SELECT * INTO b FROM public.communication_bindings WHERE id=p_binding AND organization_id=org AND owner_user_id=actor AND authority='service' AND channel='email' AND backend='unipile' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Original binding unavailable';END IF;
 IF (SELECT count(*) FROM public.audit_events WHERE organization_id=org AND actor_id=actor AND action='communications.reply_review_resolved' AND metadata->>'requestKey'=p_request::text)<>1 THEN RAISE EXCEPTION 'Ambiguous human outbound review';END IF;
 SELECT * INTO a FROM public.audit_events WHERE organization_id=org AND actor_id=actor AND action='communications.reply_review_resolved' AND metadata->>'requestKey'=p_request::text ORDER BY created_at LIMIT 1;
 p:=a.metadata->'provenance';
 IF a.id IS NULL OR a.entity_type IS DISTINCT FROM 'communication_reply_review' OR a.entity_id IS DISTINCT FROM p_binding::text||':'||p_event OR a.metadata->>'originalCode' IS DISTINCT FROM 'protocol' OR a.metadata->>'decision' IS DISTINCT FROM 'reviewed_unrelated' OR a.metadata->>'bindingId' IS DISTINCT FROM p_binding::text OR a.metadata->>'serviceEventId' IS DISTINCT FROM p_event OR a.metadata->>'resolutionReference' IS DISTINCT FROM reference OR a.metadata->'noReplyCredit' IS DISTINCT FROM 'true'::jsonb OR p->>'kind' IS DISTINCT FROM 'untracked_authenticated_outbound' OR p->>'serviceEventId' IS DISTINCT FROM p_event OR p->'noAssociation' IS DISTINCT FROM 'true'::jsonb OR (p->>'sourceKey' ~ '^[a-f0-9]{64}$') IS NOT TRUE OR (p->>'originalPayloadDigest' ~ '^[a-f0-9]{64}$') IS NOT TRUE OR (p->>'bindingDigest' ~ '^[a-f0-9]{64}$') IS NOT TRUE OR p->>'bindingDigest' IS DISTINCT FROM encode(sha256(convert_to(public.agent_channel_canonical_json(jsonb_build_array(b.application_id,b.organization_id,b.owner_user_id,b.service_connection_id,b.service_account_id,b.generation,b.channel,b.platform,b.backend)),'UTF8')),'hex') OR (SELECT count(*) FROM jsonb_object_keys(p))<>7 OR (p->>'receivedAt')::timestamptz>a.created_at THEN RAISE EXCEPTION 'Exact human outbound review proof required';END IF;
 SELECT * INTO r FROM public.communication_event_receipts WHERE binding_id=p_binding AND service_event_id=p_event AND organization_id=org AND owner_user_id=actor FOR SHARE;
 SELECT * INTO l FROM public.communication_reply_review_latches WHERE binding_id=p_binding AND service_event_id=p_event AND organization_id=org AND owner_user_id=actor FOR UPDATE;
 IF r.binding_id IS NULL OR r.event_type IS DISTINCT FROM 'account' OR r.result IS DISTINCT FROM 'review' OR r.fingerprint_version IS DISTINCT FROM 'acquire.reply.delivery.v1' OR r.payload_fingerprint IS DISTINCT FROM a.metadata->>'expectedFingerprint' OR l.code IS DISTINCT FROM 'protocol' OR l.resolved_at IS NULL OR l.resolution_reference IS DISTINCT FROM reference OR date_trunc('milliseconds',l.created_at) IS DISTINCT FROM (a.metadata->>'createdAt')::timestamptz THEN RAISE EXCEPTION 'Original app review changed';END IF;
 PERFORM communications.lock_reply_barrier(b.application_id,org);
 SELECT * INTO e FROM communications.events WHERE id::text=p_event AND application_id=b.application_id AND tenant_id=org AND owner_id=actor AND connection_id=b.service_connection_id AND account_id=b.service_account_id AND generation=b.generation AND source_namespace='reply_review/v1' AND source_event_key=p->>'sourceKey' AND event_type='account' AND direction IS NULL FOR SHARE;
 SELECT * INTO w FROM communications.webhook_inbox WHERE id=p->>'sourceKey' AND backend='unipile' AND state='processed' AND failure_code='reply_protocol' AND authenticated_at IS NOT NULL AND payload_digest=p->>'originalPayloadDigest' AND received_at=(p->>'receivedAt')::timestamptz AND received_at<a.created_at-interval '5 minutes' AND expires_at>clock_timestamp() FOR SHARE;
 -- Hold current authority through disposition; grant writers need not take the tenant barrier.
 PERFORM 1 FROM communications.webhook_receipt_routes x JOIN communications.connection_generations g ON g.connection_id=x.connection_id AND g.generation=x.generation JOIN communications.connections c ON c.id=g.connection_id AND c.current_generation=g.generation AND c.account_id=g.account_id JOIN communications.access_grants ag ON ag.application_id=g.application_id AND ag.tenant_id=g.tenant_id AND ag.owner_id=g.owner_id WHERE x.webhook_inbox_id=w.id AND x.application_id=b.application_id AND x.tenant_id=org AND x.owner_id=actor AND x.connection_id=b.service_connection_id AND x.account_id=b.service_account_id AND x.generation=b.generation AND g.application_id=b.application_id AND g.tenant_id=org AND g.owner_id=actor AND g.account_id=b.service_account_id AND g.channel='email' AND g.backend='unipile' AND g.authority='service' AND g.integration_id=w.integration_id AND c.active AND ag.revoked_at IS NULL AND ag.expires_at>clock_timestamp() FOR SHARE OF x,g,c,ag;
 IF NOT FOUND THEN RAISE EXCEPTION 'Original authenticated authority changed';END IF;
 IF e.id IS NULL OR w.id IS NULL OR e.webhook_inbox_id IS DISTINCT FROM w.id OR e.occurred_at>w.received_at OR NOT EXISTS(SELECT 1 FROM communications.webhook_receipt_routes x JOIN communications.connection_generations g ON g.connection_id=x.connection_id AND g.generation=x.generation JOIN communications.connections c ON c.id=g.connection_id AND c.current_generation=g.generation AND c.account_id=g.account_id JOIN communications.access_grants ag ON ag.application_id=g.application_id AND ag.tenant_id=g.tenant_id AND ag.owner_id=g.owner_id WHERE x.webhook_inbox_id=w.id AND x.application_id=b.application_id AND x.tenant_id=org AND x.owner_id=actor AND x.connection_id=b.service_connection_id AND x.account_id=b.service_account_id AND x.generation=b.generation AND g.application_id=b.application_id AND g.tenant_id=org AND g.owner_id=actor AND g.account_id=b.service_account_id AND g.channel='email' AND g.backend='unipile' AND g.authority='service' AND g.integration_id=w.integration_id AND c.active AND ag.revoked_at IS NULL AND ag.expires_at>clock_timestamp()) OR EXISTS(SELECT 1 FROM communications.operation_journal j WHERE j.connection_id=b.service_connection_id AND j.account_id=b.service_account_id AND j.generation=b.generation) THEN RAISE EXCEPTION 'Original authenticated untracked source changed';END IF;
 SELECT * INTO sl FROM communications.reply_review_latches WHERE event_id=e.id AND application_id=b.application_id AND tenant_id=org AND owner_id=actor AND code='protocol' FOR UPDATE;
 IF sl.event_id IS NULL OR sl.resolved_at IS NOT NULL AND sl.resolution_reference IS DISTINCT FROM reference THEN RAISE EXCEPTION 'Original service review changed';END IF;
 IF sl.resolved_at IS NULL THEN UPDATE communications.reply_review_latches SET resolved_at=clock_timestamp(),resolution_reference=reference WHERE event_id=e.id;END IF;
 RETURN true;
END $$;
